it('rejects a case-insensitive duplicate username without saving', async () => {
  const user = userEvent.setup();

  mocks.users.push(
    createUser({
      id: 'existing-writer',
      displayName: 'Existing Writer',
      username: 'existing_writer',
    }),
  );

  renderAdminWorkflows('/users');

  await user.type(
    screen.getByRole('textbox', { name: 'Display name' }),
    'Duplicate Writer',
  );
  await user.type(
    screen.getByRole('textbox', { name: 'Username' }),
    'EXISTING_WRITER',
  );
  await user.type(
    screen.getByLabelText('Password'),
    'local-password',
  );
  await user.click(
    screen.getByRole('button', { name: 'Create User' }),
  );

  expect(
    screen.getByText('Username is already in use.'),
  ).toBeInTheDocument();
  expect(mocks.saveUsers).not.toHaveBeenCalled();
  expect(
    mocks.users.filter(
      (storedUser) =>
        storedUser.username.toLowerCase() === 'existing_writer',
    ),
  ).toHaveLength(1);
});

