it('confirms and persists deletion of an eligible user', async () => {
  const user = userEvent.setup();
  const confirmSpy = vi
    .spyOn(window, 'confirm')
    .mockReturnValue(true);

  renderAdminWorkflows('/users');

  await user.click(
    screen.getByRole('button', {
      name: 'Delete Eligible Writer',
    }),
  );

  expect(confirmSpy).toHaveBeenCalledWith(
    'Delete this user? This action cannot be undone.',
  );
  expect(mocks.saveUsers).toHaveBeenCalledTimes(1);
  expect(mocks.saveUsers).toHaveBeenCalledWith([
    expect.objectContaining({ id: DEFAULT_ADMIN.id }),
    expect.objectContaining({ id: ADMIN_SESSION.userId }),
  ]);

  await waitFor(() => {
    expect(
      screen.queryByText('Eligible Writer'),
    ).not.toBeInTheDocument();
  });
  expect(
    mocks.users.some((storedUser) => storedUser.id === 'user-1'),
  ).toBe(false);
});

