it('renders a valid post and preserves its whitespace as text', () => {
  const content =
    'First paragraph.\n\nSecond paragraph.\n  Indented local note.';

  mocks.posts = [
    createPost({
      title: 'Whitespace-preserved story',
      content,
    }),
  ];

  renderBlogWorkflows('/blog/post-1');

  const article = screen.getByRole('article');
  const contentElement = article.querySelector(
    '.whitespace-pre-wrap',
  );

  expect(
    within(article).getByRole('heading', {
      level: 1,
      name: 'Whitespace-preserved story',
    }),
  ).toBeInTheDocument();
  expect(contentElement).not.toBeNull();
  expect(contentElement).toHaveClass(
    'whitespace-pre-wrap',
    'break-words',
  );
  expect(contentElement.textContent).toBe(content);
});

