it('stores and returns a minimal defensive copy of a valid session', async () => {
  const { getSession, setSession } = await loadAuthAdapter();
  const session = {
    ...createSession(),
    temporaryValue: 'must-not-be-persisted',
  };

  expect(setSession(session)).toEqual({ ok: true });

  const storedSession = JSON.parse(
    window.localStorage.getItem(STORAGE_KEYS.session),
  );

  expect(storedSession).toEqual(createSession());
  expect(storedSession).not.toHaveProperty('password');
  expect(storedSession).not.toHaveProperty('temporaryValue');

  session.displayName = 'Caller mutation';

  const firstRead = getSession();

  expect(firstRead).toEqual(createSession());

  firstRead.displayName = 'Returned value mutation';

  expect(getSession()).toEqual(createSession());
});

