it('seeds coherent users and reference-relative posts on the first read', async () => {
  const { getPosts, getUsers } = await loadStorageAdapter();

  const users = getUsers();
  const posts = getPosts();

  expect(users).toHaveLength(4);
  expect(users[0]).toEqual(DEFAULT_ADMIN);
  expect(posts).toHaveLength(5);

  const expectedDayOffsets = [1, 4, 9, 16, 24];
  const referenceTimestamp = Date.parse(REFERENCE_FIXTURE_DATE);
  const demoUserIds = new Set(users.slice(1).map((user) => user.id));

  posts.forEach((post, index) => {
    const expectedDate = new Date(
      referenceTimestamp -
        expectedDayOffsets[index] * DAY_IN_MILLISECONDS,
    ).toISOString();

    expect(post.createdAt).toBe(expectedDate);
    expect(demoUserIds.has(post.authorId)).toBe(true);
    expect(
      users.some(
        (user) =>
          user.id === post.authorId &&
          user.displayName === post.authorName,
      ),
    ).toBe(true);
  });

  expect(
    JSON.parse(window.localStorage.getItem(STORAGE_KEYS.users)),
  ).toEqual(users);
  expect(
    JSON.parse(window.localStorage.getItem(STORAGE_KEYS.posts)),
  ).toEqual(posts);
});

