it('reports denied storage writes and preserves the prior stored value', async () => {
  const originalPosts = [createPost()];
  const replacementPosts = [
    createPost({
      id: 'post-2',
      title: 'Replacement post',
    }),
  ];

  window.localStorage.setItem(
    STORAGE_KEYS.posts,
    JSON.stringify(originalPosts),
  );

  const setItemSpy = vi
    .spyOn(Storage.prototype, 'setItem')
    .mockImplementation(() => {
      throw new DOMException('Storage access denied.', 'SecurityError');
    });
  const { savePosts } = await loadStorageAdapter();

  expect(savePosts(replacementPosts)).toEqual({
    ok: false,
    error: 'STORAGE_UNAVAILABLE',
  });

  setItemSpy.mockRestore();

  expect(
    JSON.parse(window.localStorage.getItem(STORAGE_KEYS.posts)),
  ).toEqual(originalPosts);
});

