it('updates uncontrolled input, debounces search, and clears immediately', async () => {
  vi.useFakeTimers();
  const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
  const onSearch = vi.fn();
  const onChange = vi.fn();
  const onClear = vi.fn();

  render(
    <SearchInput
      defaultValue=""
      onSearch={onSearch}
      onChange={onChange}
      onClear={onClear}
      debounceMs={250}
      placeholder="Search records"
    />
  );

  const input = screen.getByRole('textbox', { name: 'Search records' });
  await user.type(input, 'abc');

  expect(onChange).toHaveBeenNthCalledWith(1, 'a');
  expect(onChange).toHaveBeenNthCalledWith(3, 'abc');
  expect(onSearch).not.toHaveBeenCalled();

  vi.advanceTimersByTime(250);
  expect(onSearch).toHaveBeenCalledWith('abc');

  await user.click(screen.getByRole('button', { name: 'Clear search' }));
  expect(input).toHaveValue('');
  expect(onClear).toHaveBeenCalledTimes(1);
  expect(onSearch).toHaveBeenLastCalledWith('');

  vi.useRealTimers();
});

it('submits immediately on Enter and clears on Escape', async () => {
  const user = userEvent.setup();
  const onSearch = vi.fn();
  const onSubmit = vi.fn();

  render(<SearchInput defaultValue="seed" onSearch={onSearch} onSubmit={onSubmit} />);

  const input = screen.getByRole('textbox', { name: 'Search...' });
  await user.click(input);
  await user.keyboard('{Enter}');

  expect(onSearch).toHaveBeenCalledWith('seed');
  expect(onSubmit).toHaveBeenCalledTimes(1);

  await user.keyboard('{Escape}');
  await waitFor(() => expect(input).toHaveValue(''));
  expect(onSearch).toHaveBeenLastCalledWith('');
});

