  window.localStorage.setItem('unrelated', JSON.stringify('keep-me'));
  expect(remove(STORAGE_KEYS.USER_PROFILE)).toBe(true);
  expect(load(STORAGE_KEYS.USER_PROFILE, 'fallback')).toBe('fallback');

