it('renders item count summary when only one page exists and selector is hidden', () => {
  render(
    <Pagination
      page={1}
      totalPages={1}
      totalItems={7}
      pageSize={10}
      onPageChange={() => {}}
      showPageSizeSelector={false}
      showItemCount
    />,
  );

  expect(screen.getByText('Showing 1–7 of 7 items')).toBeInTheDocument();
  expect(screen.queryByRole('navigation', { name: /pagination/i })).not.toBeInTheDocument();
});

it('renders navigation with ellipses for large page sets', () => {
  render(
    <Pagination
      page={5}
      totalPages={10}
      totalItems={100}
      pageSize={10}
      onPageChange={() => {}}
      showPageSizeSelector={false}
      maxVisiblePages={5}
    />,
  );

  expect(screen.getByRole('navigation', { name: 'Pagination' })).toBeInTheDocument();
  expect(screen.getByLabelText('Go to page 1')).toBeInTheDocument();
  expect(screen.getByLabelText('Page 5, current page')).toBeInTheDocument();
  expect(screen.getAllByText('…').length).toBeGreaterThan(0);
});

it('invokes page change callbacks for next, previous, and direct page clicks', () => {
  const onPageChange = vi.fn();
  render(
    <Pagination
      page={3}
      totalPages={5}
      totalItems={50}
      pageSize={10}
      onPageChange={onPageChange}
      showPageSizeSelector={false}
    />,
  );

  fireEvent.click(screen.getByLabelText('Go to previous page'));
  fireEvent.click(screen.getByLabelText('Go to next page'));
  fireEvent.click(screen.getByLabelText('Go to page 4'));

  expect(onPageChange).toHaveBeenNthCalledWith(1, 2);
  expect(onPageChange).toHaveBeenNthCalledWith(2, 4);
  expect(onPageChange).toHaveBeenNthCalledWith(3, 4);
});

it('does not invoke page change when clicking disabled boundary controls', () => {
  const onPageChange = vi.fn();
  render(
    <Pagination
      page={1}
      totalPages={5}
      totalItems={50}
      pageSize={10}
      onPageChange={onPageChange}
      showPageSizeSelector={false}
    />,
  );

  const previousButtons = screen.getAllByLabelText('Go to previous page');
  fireEvent.click(previousButtons[previousButtons.length - 1]);
  fireEvent.click(screen.getByLabelText('Page 1, current page'));

  expect(onPageChange).not.toHaveBeenCalled();
});

it('invokes page size change callback from selector', () => {
  const onPageSizeChange = vi.fn();
  render(
    <Pagination
      page={1}
      totalPages={3}
      totalItems={30}
      pageSize={10}
      onPageChange={() => {}}
      onPageSizeChange={onPageSizeChange}
    />,
  );

  fireEvent.change(screen.getByLabelText('Items per page'), { target: { value: '20' } });
  expect(onPageSizeChange).toHaveBeenCalledWith(20);
});

