  expect(authService.getSession().isAuthenticated).toBe(false);
});

it('refreshes an active session and extends expiration', () => {
  vi.useFakeTimers();
  vi.setSystemTime(new Date('2024-01-01T00:00:00Z'));

  const loginResult = authService.login('jane.doe', 'password123');
  const firstExpiry = loginResult.expiresAt;

  vi.setSystemTime(new Date('2024-01-01T00:05:00Z'));
  const refreshResult = authService.refreshSession();

  expect(refreshResult.success).toBe(true);
  expect(new Date(refreshResult.expiresAt).getTime()).toBeGreaterThan(new Date(firstExpiry).getTime());
});

it('tracks session warning once and resets it when extending the session', () => {
  vi.useFakeTimers();
  vi.setSystemTime(new Date('2024-01-01T00:00:00Z'));
  authService.login('jane.doe', 'password123');

  const warningSpy = vi.fn();
  const expiredSpy = vi.fn();
  expect(sessionManager.startMonitoring({ onWarning: warningSpy, onExpired: expiredSpy })).toBe(true);

  vi.setSystemTime(new Date('2024-01-01T00:13:30Z'));
  const warningStatus = sessionManager.checkSessionStatus();
  expect(warningStatus.status).toBe('warning');
  expect(warningSpy).toHaveBeenCalledTimes(1);
  expect(getItem('hcp_session_warning_shown', false)).toBe(true);

  const extendResult = sessionManager.extendSession();
  expect(extendResult.success).toBe(true);
  expect(getItem('hcp_session_warning_shown', true)).toBe(false);

  const activeStatus = sessionManager.checkSessionStatus();
  expect(activeStatus.status).toBe('active');
  expect(expiredSpy).not.toHaveBeenCalled();
});

