  expect(formatDate('2024-03-15')).toBe('03/15/2024');
  expect(formatDate(new Date(2024, 2, 15, 13, 5), { format: 'MM/DD/YYYY hh:mm A' })).toBe('03/15/2024 01:05 PM');
});

it('formats relative dates for past, future, and immediate times', () => {
  vi.useFakeTimers();
  vi.setSystemTime(new Date('2024-01-10T12:00:00Z'));

  expect(formatRelativeDate('2024-01-10T11:59:45Z')).toBe('just now');
  expect(formatRelativeDate('2024-01-10T10:00:00Z')).toBe('2 hours ago');
  expect(formatRelativeDate('2024-01-10T15:00:00Z')).toBe('in 3 hours');
});

