  expect(formatPhoneNumber('18005550199')).toBe('1-800-555-0199');
  expect(formatPhoneNumber('ext-55')).toBe('ext-55');
});

it('caps progress percentage at 100 and handles zero max', () => {
  expect(formatProgressPercentage(150, 100)).toBe('100%');
  expect(formatProgressPercentage(10, 0)).toBe('0%');
});

it('sanitizes queries and enforces minimum length', () => {
  expect(sanitizeQuery('  <claims>   info  ')).toBe('claims info');
  expect(isValidQuery(' a ')).toBe(false);
  expect(isValidQuery(' claims ')).toBe(true);
});

it('returns filtered portal search results with metadata', () => {
  const result = performSearch('claims', { category: 'page', limit: 10 });

  expect(result.query).toBe('claims');
  expect(result.hasResults).toBe(true);
  expect(result.category).toBe('page');
  expect(result.results.every((entry) => entry.category === 'page')).toBe(true);
  expect(result.results.some((entry) => entry.title === 'Claims')).toBe(true);
});

it('returns suggestions only for valid partial queries', () => {
  expect(getSuggestions('c')).toEqual([]);
  const suggestions = getSuggestions('doc');
  expect(suggestions.length).toBeGreaterThan(0);
  expect(suggestions.some((entry) => entry.title === 'Documents')).toBe(true);
});

it('combines portal and faq results in searchAll', () => {
  const result = searchAll('telemedicine');

  expect(result.portalResults.length).toBeGreaterThan(0);
  expect(result.faqResults.length).toBeGreaterThan(0);
  expect(result.totalResults).toBe(result.portalResults.length + result.faqResults.length);
  expect(result.hasResults).toBe(true);
});

it('groups results by category and resolves labels', () => {
  const grouped = groupResultsByCategory([
    { id: '1', category: 'page' },
    { id: '2', category: 'faq' },
    { id: '3' },
  ]);

  expect(Object.keys(grouped)).toEqual(['page', 'faq', 'other']);
  expect(grouped.other).toHaveLength(1);
  expect(getCategoryLabel('faq')).toBe('Help & FAQs');
  expect(getCategoryLabel('unknown')).toBe('Other');
});

