});

it('filters by persona and supports read, add and dismiss operations', async () => {
  const user = userEvent.setup();

  render(
    <PersonaProvider>
      <NotificationProvider>
        <NotificationProbe />
      </NotificationProvider>
    </PersonaProvider>
  );

  expect(Number(screen.getByTestId('notif-count').textContent)).toBeGreaterThan(0);
  const initialUnread = Number(screen.getByTestId('unread-count').textContent);

  await user.click(screen.getByRole('button', { name: 'mark-first-read' }));
  await waitFor(() => {
    expect(Number(screen.getByTestId('unread-count').textContent)).toBeLessThanOrEqual(initialUnread);
  });

  const countBeforeAdd = Number(screen.getByTestId('notif-count').textContent);
  await user.click(screen.getByRole('button', { name: 'add' }));
  await waitFor(() => {
    expect(Number(screen.getByTestId('notif-count').textContent)).toBe(countBeforeAdd + 1);
  });
  expect(screen.getByTestId('first-id').textContent).toMatch(/^notif_/);

  const countAfterAdd = Number(screen.getByTestId('notif-count').textContent);
  await user.click(screen.getByRole('button', { name: 'dismiss-first' }));
  await waitFor(() => {
    expect(Number(screen.getByTestId('notif-count').textContent)).toBe(countAfterAdd - 1);
  });

  await user.click(screen.getByRole('button', { name: 'mark-all-read' }));
  expect(screen.getByTestId('unread-count')).toHaveTextContent('0');
});

it('debounces search, submits immediately on Enter, and clears on Escape', async () => {
  const user = userEvent.setup();
  const onSearch = vi.fn();
  const onChange = vi.fn();
  const onClear = vi.fn();
  const onSubmit = vi.fn();

  render(
    <SearchInput
      defaultValue=""
      onSearch={onSearch}
      onChange={onChange}
      onClear={onClear}
      onSubmit={onSubmit}
      debounceMs={50}
      placeholder="Search records"
    />
  );

  const input = screen.getByRole('textbox', { name: 'Search records' });
  await user.type(input, 'abc');
  expect(onChange).toHaveBeenCalledTimes(3);

  await waitFor(() => {
    expect(onSearch).toHaveBeenCalledWith('abc');
  });

  fireEvent.keyDown(input, { key: 'Enter' });
  expect(onSubmit).toHaveBeenCalled();
  expect(onSearch).toHaveBeenLastCalledWith('abc');

  fireEvent.keyDown(input, { key: 'Escape' });
  expect(onClear).toHaveBeenCalled();
  expect(onSearch).toHaveBeenLastCalledWith('');
  expect(input).toHaveValue('');
});

