it('PermissionGate hides, disables, or shows fallback based on authorization rules', () => {
  render(
    <PersonaProvider>
      <>
        <PermissionGate requiredAction={PERMISSIONS.MANAGE_USERS}>
          <button>hidden action</button>
        </PermissionGate>

        <PermissionGate
          requiredAction={PERMISSIONS.MANAGE_USERS}
          behavior="disabled"
          className="extra-class"
        >
          <button>disabled action</button>
        </PermissionGate>

        <PermissionGate
          requiredAction={[PERMISSIONS.VIEW_DASHBOARD, PERMISSIONS.MANAGE_USERS]}
          matchAll
          behavior="placeholder"
          fallback={<span>no access</span>}
        >
          <button>placeholder action</button>
        </PermissionGate>

        <PermissionGate requiredAction={[PERMISSIONS.VIEW_DASHBOARD, PERMISSIONS.MANAGE_USERS]}>
          <button>any-match action</button>
        </PermissionGate>
      </>
    </PersonaProvider>
  );

  expect(screen.queryByText('hidden action')).not.toBeInTheDocument();
  expect(screen.getByText('disabled action').parentElement).toHaveAttribute('aria-disabled', 'true');
  expect(screen.getByText('disabled action').parentElement.className).toContain('extra-class');
  expect(screen.getByText('no access')).toBeInTheDocument();
  expect(screen.getByText('any-match action')).toBeInTheDocument();
});

